<?php
require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';use MongoDB\BSON\ObjectId;
setJsonResponse();handleCors();logRequest();requireLogin();try{$db=getDatabase();$users=$db->users;$id=new ObjectId($_SESSION['user_id']);if($_SERVER['REQUEST_METHOD']==='GET'){$u=$users->findOne(['_id'=>$id]);sendResponse(true,'Profile loaded',['name'=>$u['name']??'','email'=>$u['email']??'','phone'=>$u['phone']??'','license'=>$u['license']??'','role'=>$u['role']??'user']);}if($_SERVER['REQUEST_METHOD']==='PUT'){$d=json_decode(file_get_contents('php://input'),true);$name=trim($d['name']??'');$email=strtolower(trim($d['email']??''));$phone=trim($d['phone']??'');$license=trim($d['license']??'');if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL))sendResponse(false,'Please enter a valid name and email.',null,400);$other=$users->findOne(['email'=>$email,'_id'=>['$ne'=>$id]]);if($other)sendResponse(false,'That email is already in use.',null,409);$users->updateOne(['_id'=>$id],['$set'=>['name'=>$name,'email'=>$email,'phone'=>$phone,'license'=>$license]]);$_SESSION['user_name']=$name;$_SESSION['user_email']=$email;sendResponse(true,'Profile updated successfully.');}sendResponse(false,'Method not allowed.',null,405);}catch(Exception $e){sendResponse(false,'Profile operation failed.',null,500);}
